import { performance } from "node:perf_hooks";
import { configureOutputStorage, outputUsage } from "../../scripts/bot-improvement/output-storage.ts";
import assert from "node:assert/strict";
import { mkdir, mkdtemp, readFile, writeFile, rm } from "node:fs/promises";
import path from "node:path";
import { cardCode } from "../../src/battle/duel/contracts/ids.ts";
import {
  digest,
  identity,
  schedule,
} from "../../scripts/bot-improvement/session-fixtures.ts";
import {
  encodeLogRecord as line,
  parseGameLog,
  decodeLogRecord,
  decodeLog,
  targetLossView,
} from "../../scripts/bot-improvement/game-log.ts";
import {
  publishTextCompletion,
  finalizedText,
} from "../../scripts/bot-improvement/analysis-text-evidence.ts";
import { prepareAnalysisSlices } from "../../scripts/bot-improvement/analysis-slices.ts";
import type { AnalysisBinding } from "../../scripts/bot-improvement/analysis-contract.ts";

const put = async (file: string, value: unknown) => {
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(
    file,
    typeof value === "string" ? value : JSON.stringify(value),
  );
};
async function run(count: number) {
  await mkdir(".tmp", { recursive: true });
  const session = await mkdtemp(path.join(root, `files-${count}-`));
  try {
    const b = {
      kind: "module",
      module: "builtin:basic",
      configuration: {},
      deck: { main: [cardCode(1)], extra: [], side: [] },
      files: { "bot.mjs": digest("bot") },
    };
    const bot = { ...b, identity: identity(b) };
    const matches = schedule("slice", bot.deck, [], 12);
    const f = {
      schemaVersion: 1,
      setupSeed: "slice",
      inputsIdentity: "inputs",
      profile: "mr5",
      protocol: {},
      target: bot,
      opponents: [],
      files: { "versions/initial/bot.mjs": digest("bot") },
      matches,
    };
    const frozen = { ...f, identity: identity(f) };
    const fixture = {
      path: path.join(session, "fixture"),
      identity: frozen.identity,
    };
    await put(path.join(fixture.path, "manifest.json"), frozen);
    await put(path.join(fixture.path, "versions/initial/bot.mjs"), "bot");
    await put(path.join(session, "config.json"), {
      schemaVersion: 1,
      fixture,
      limits: { analysisWorkers: 2 },
      analysisTiming: "after-evaluation",
    });
    await put(path.join(session, "iterations/iteration-0001/manifest.json"), {
      schemaVersion: 1,
      iteration: 1,
      fixture,
      self: { identity: bot.identity },
      control: { identity: bot.identity },
      opponents: [],
      runnerIdentity: "runner",
    });
    const body = {
      schemaVersion: 1,
      fixtureIdentity: frozen.identity,
      candidateIdentity: bot.identity,
      selfIdentity: bot.identity,
      matches: matches.map((match) => ({
        match,
        identities: [bot.identity, bot.identity],
      })),
    };
    const execution = { ...body, identity: identity(body) };
    await put(path.join(session, "run.job.json"), execution);
    await put(path.join(session, "proposal.txt"), "reason changes");
    const ref = async (p: string) => ({
      path: p,
      sha256: digest(await readFile(path.join(session, p))),
    });
    const binding: AnalysisBinding = {
      iteration: 1,
      role: "candidate",
      root: "run",
      execution: await ref("run.job.json"),
      proposal: await ref("proposal.txt"),
    };
    const lost = new Set([1, 2, 9, 10, 12]);
    async function match(number: number) {
      const item = execution.matches[number - 1]!,
        root = `run/matches/${item.match.id}`;
      let index =
        "ASCENCIO_MATCH_LOG\t2\n" +
        line("MATCH", {
          run_id: execution.identity,
          match_id: item.match.id,
          status: "completed",
          sideboarding: { status: "completed" },
        }) +
        line("MANIFEST", {}) +
        line("FIXTURE", item) +
        line("REPORT_A", {}) +
        line("REPORT_B", {});
      for (let n = 1; n <= 4; n++) {
        const winner = n === 1 && lost.has(number) ? "b" : n === 2 ? "a" : null;
        const g = {
          game_id: `${item.match.id}-game-${n}`,
          number: n,
          stage: n < 3 ? "pre_side" : "post_side",
          starter: n % 2 ? "a" : "b",
          status: "completed",
          winner,
          draw: winner === null,
          evidence_sha256: digest("evidence"),
        };
        let text = "ASCENCIO_GAME_LOG\t2\n" + line("GAME", g);
        for (const actor of ["a", "b"]) {
          text +=
            line("ACTOR", actor) +
            line("RECORD", {
              game_id: g.game_id,
              stage: g.stage,
              starting_player: g.starter,
              status: g.status,
            });
          text +=
            line("SIDEBOARD", {}) +
            line("INITIAL", {
              visible:
                actor === "b"
                  ? "OPPONENT_PRIVATE"
                  : winner === "b"
                    ? "LOSS_ONLY"
                    : "WIN_DRAW_ONLY",
            });
          text += line("EVENT", {
            kind: "decision",
            sequence: 1,
            decision_id: `${actor}-decision-${n}`,
            prompt: {
              choices: {
                choice: [{ id: "exact-instance-42", label: "visible action" }],
              },
            },
            selected_choice_ids: { choice_id: ["exact-instance-42"] },
          });
          text +=
            line("RESULT", {
              outcome:
                winner === null ? "draw" : winner === actor ? "win" : "loss",
              evidence_sha256: g.evidence_sha256,
            }) + line("END_ACTOR", actor);
        }
        text += line("END_GAME", g.game_id);
        await put(path.join(session, root, `games/game-${n}/game.log`), text);
        if (n === 1) {
          assert.equal(
            (
              parseGameLog(text).actors[0].timeline.entry[0]!.prompt as {
                choices: { choice: { id: string }[] };
              }
            ).choices.choice[0]!.id,
            "exact-instance-42",
          );
          if (winner !== "b")
            assert.throws(() => targetLossView(text), /Only completed/);
        }
        index += line("GAME_REF", {
          number: n,
          path: `games/game-${n}/game.log`,
        });
      }
      index += line("END_MATCH", item.match.id);
      await put(path.join(session, root, "match.log"), index);
      return await publishTextCompletion(session, root, {
        match: item.match.id,
        executionIdentity: execution.identity,
        fixtureIdentity: frozen.identity,
        candidateIdentity: bot.identity,
        opponentIdentity: bot.identity,
        item,
      });
    }

    for (let n = 1; n <= 12; n++) await match(n);
    await configureOutputStorage(session, 50000000000);
    await mkdir(path.join(session, "unrelated"));
    for (let n = 0; n < count; n++) await writeFile(path.join(session, "unrelated", String(n)), "x");
    const start = performance.now();
    const synced = await prepareAnalysisSlices(session, { action: "sync", binding });
    const prepared = performance.now();
    const a = {iteration: 1, role: "candidate" as const};
    const claim = (await prepareAnalysisSlices(session, {action: "claim", ...a, owner: "mechanical-fixture"})).claim!;
    const packet = JSON.parse(await readFile(path.join(session,claim.packet.path),"utf8"));
    const reports = [];
    for (const job of packet.jobs) {
      const file = `fixture-reports/${job.match}.md`;
      await put(path.join(session,file), `# Mechanical fixture\nJob: ${job.id}\nPacket: ${job.packetSha256}\n\n` + job.losses.map((loss: any) => `- G${loss.game} | - | unclear | Fixture only | No causal claim\n`).join(""));
      reports.push(await ref(file));
    }
    const reportStart = performance.now();
    const done = await prepareAnalysisSlices(session, {action: "complete", ...a, slice: claim.id, token: claim.claim!.token, reports});
    const end = performance.now();
    assert.equal(done.complete,true);
    const usage = await outputUsage(session,true);
    return {count,session,prepareMs:prepared-start,reportMs:end-reportStart,workflowMs:end-start,usage,losses:packet.jobs.reduce((n:number,j:any)=>n+j.losses.length,0)};
  } finally { /* Retain isolated evidence for review. */ }
}
const root = path.resolve(`.tmp/perf-iterations/${process.argv[2]}`);
await mkdir(root);
const sources = Object.fromEntries(await Promise.all(["analysis-output.ts", "analysis-slices.ts", "prepare-analyses.ts", "batch-storage-lease.ts", "replay-output-budget.ts", "output-storage.ts", "session-checkpoint.ts"].map(async file => [file, digest(await readFile(`scripts/bot-improvement/${file}`))])));
const runs=[];
for(const count of [0,1000,10000]) for(let repeat=0;repeat<3;repeat++) {
 const result=await run(count);runs.push({...result,repeat});console.log(JSON.stringify(runs.at(-1)));
 await writeFile(path.join(root,"measurements.json"),JSON.stringify({sources, node:process.version, scope:"Twelve synthetic matches, complete slice preparation and mechanical reports for every loss. No AI analysis or games. Quota enabled; setup excluded.",runs},null,2));
}

