import { readFile, writeFile } from 'node:fs/promises';
import { performance } from 'node:perf_hooks';
import { createHash } from 'node:crypto';
import { NativeMatchEvidence as Before } from './evidence-before-direct.ts';
import { NativeMatchEvidence as After } from '../../scripts/bot-improvement/typescript-native-evidence.ts';
import { parseGameLog } from '../../scripts/bot-improvement/game-log.ts';
import { benchmarkProvenance } from '../../scripts/bot-improvement/benchmark-provenance.ts';
const input='.tmp/typescript-production-200-games-v3/typescript-native/payload';
const job=JSON.parse(await readFile(`${input}/execution.json`,'utf8'));
const examples=[];
const hashes=[];
for(const item of job.matches.slice(0,12)) {
 const a=new Before(job,item), b=new After(job,item);
 for(let n=1;n<=4;n++) {
  const bytes=await readFile(`${input}/matches/${item.match.id}/native/games/game-${n}/game.log`,'utf8');
  hashes.push(createHash('sha256').update(bytes).digest('hex'));
  const parsed=parseGameLog(bytes);
  for(const writer of [a,b]) {
   writer.games.push(parsed.neutral);
   writer.records.push(parsed.actors);
   if(n===3)writer.sideboarding=parsed.sideboarding;
  }
 }
 examples.push({before:a,after:b});
}
const provenance=benchmarkProvenance(hashes,{workers:[1],evidenceMode:'full game serialization from parsed real records; no simulation'});
const baselineSource=await readFile('.tmp/perf-iterations/evidence-before-direct.ts','utf8');
const runs=[];let expected;
for(let repeat=0;repeat<5;repeat++)for(const variant of repeat%2?['after','before']:['before','after']) {
 const cpu=process.cpuUsage(),begin=performance.now(),texts=[];
 for(const example of examples)for(let i=0;i<4;i++)texts.push(example[variant].serializeGame(i));
 const ms=performance.now()-begin,cpuUsed=process.cpuUsage(cpu);
 const fingerprint=createHash('sha256').update(texts.join('')).digest('hex');
 if(expected!==undefined&&fingerprint!==expected)throw Error('Serialized bytes differ');
 expected=fingerprint;
 const row={repeat,variant,ms,cpu:cpuUsed,rss:process.memoryUsage().rss,bytes:texts.reduce((n,t)=>n+Buffer.byteLength(t),0),fingerprint};
 runs.push(row);console.log(JSON.stringify(row));
 await writeFile('.tmp/perf-iterations/serialize-measurements.json',JSON.stringify({provenance,baselineSource,runs},null,2));
}

