import { readFile,writeFile } from 'node:fs/promises';
import { performance } from 'node:perf_hooks';
import { runReplayPool } from '../../scripts/bot-improvement/run-replay-pool.ts';
import { identity } from '../../scripts/bot-improvement/session-fixtures.ts';
import { benchmarkProvenance } from '../../scripts/bot-improvement/benchmark-provenance.ts';
const [label,count]=process.argv.slice(2),workers=Number(count);
if(!label||!/^[a-z0-9-]+$/.test(label))throw Error('Fresh label required');
const request='.tmp/perf-iterations/replay-request.json';
const provenance=benchmarkProvenance(JSON.parse(await readFile(request,'utf8')),{workers:[workers],evidenceMode:'four full control/takeover cases including discovery, freezing and durable evidence'});
const start=performance.now();
const result=await runReplayPool({request,out:`.tmp/perf-iterations/${label}`,workers});
const elapsedMs=performance.now()-start;
if(result.status!=='complete'||result.failed||result.ignored||result.cancelled||result.complete!==4)throw Error('Incomplete replay fixture');
const fingerprint=identity(result.rows.map(r=>({id:r.id,control:r.result.control,alternative:r.result.alternative,choiceChanged:r.result.choiceChanged,convertedLossToWin:r.result.convertedLossToWin})).sort((a,b)=>a.id.localeCompare(b.id)));
const data={label,provenance,workers,elapsedMs,fingerprint,result};
await writeFile(`.tmp/perf-iterations/${label}/measurement.json`,JSON.stringify(data,null,2));
console.log(JSON.stringify({label,workers,elapsedMs,fingerprint}));

