import { readFile,writeFile } from 'node:fs/promises';
import { spawn } from 'node:child_process';
const source='scripts/bot-improvement/replay-game-decision.ts';
const before=await readFile('.tmp/perf-iterations/replay-before-dead-format.ts','utf8');
const after=await readFile(source,'utf8');
