              ? Object.fromEntries(
                  Object.keys(x)
                    .sort()
                    .filter(
                      (k) =>
                        !Array.isArray((x as Record<string, unknown>)[k]) ||
                        ((x as Record<string, unknown>)[k] as unknown[]).length,
                    )
                    .map((k) => [
                      k,
                      canonical((x as Record<string, unknown>)[k]),
                    ]),
