import {readFile,writeFile} from 'node:fs/promises';
import {decodeLog,parseGameLog} from '../../scripts/bot-improvement/game-log.ts';
import {mapPlayers} from '../../scripts/bot-improvement/typescript-match-worker.ts';
import {DecisionReplay} from '../../scripts/bot-evaluation/decision-replay.ts';
const request=JSON.parse(await readFile('.tmp/perf-iterations/replay-request.json','utf8'));
const results=[];
for(const [beforeIndex,afterIndex] of [[0,1],[3,2],[4,5],[7,6]]) {
 const before=JSON.parse(await readFile(`.tmp/perf-iterations/replay-host-before-${beforeIndex}/measurement.json`,'utf8'));
 const after=JSON.parse(await readFile(`.tmp/perf-iterations/replay-host-after-${afterIndex}/measurement.json`,'utf8'));
 if(before.fingerprint!==after.fingerprint)throw Error('Replay outcomes or choices changed');
 let timelines=0;
 for(const row of before.result.rows) {
  const candidate=after.result.rows.find(r=>r.id===row.id);
  const reason=request.reasons.find(r=>r.id===row.reason);
  const source=reason.cases.find(c=>`${reason.id}/${c.id}`===row.id);
  const neutral=parseGameLog(await readFile(`${source.game}/game.log`,'utf8')).neutral;
  const order=neutral.starter==='a'?[0,1]:[1,0];
  for(const branch of ['control','alternative']) {
   const read=async folder=>decodeLog(await readFile(`${folder}/${branch}.log`,'utf8'),'ASCENCIO_REPLAY_LOG\t2').map(l=>l.value);
   const [left,right]=await Promise.all([read(row.output),read(candidate.output)]);
   const records=[{initial:null,timeline:{entry:[]}},{initial:null,timeline:{entry:[]}}];
   for(const f of left) {
    if(f.type==='initial')records[order[f.actor]].initial=mapPlayers(f.initial,order[0]===1);
    if(f.type==='event'||f.type==='decision')records[order[f.actor]].timeline.entry.push(mapPlayers(f.entry,order[0]===1));
   }
   const decision=records.flatMap(r=>r.timeline.entry).find(e=>e.kind==='decision');
   const verifier=new DecisionReplay({actor:decision.actor,decision:decision.decision_id,records},order);
   const counts=[0,0];
   for(const f of right) {
    if(f.type==='initial')verifier.initial(f.actor,f.initial);
    if(f.type==='event'||f.type==='decision'){verifier.event(f.actor,f.entry);counts[order[f.actor]]++;}
   }
   if(counts.some((count,i)=>count!==records[i].timeline.entry.length))throw Error('Replay timeline coverage changed');
   timelines+=2;
  }
 }
 const result={before:before.label,after:after.label,workers:before.workers,timelines,fingerprint:before.fingerprint};results.push(result);console.log(JSON.stringify(result));
}
await writeFile('.tmp/perf-iterations/replay-host-behavior.json',JSON.stringify(results,null,2));

