for(const item of job.matches.slice(0,12))for(let n=1;n<=4;n++)inputs.push(await readFile(`${root}/matches/${item.match.id}/native/games/game-${n}/game.log`,'utf8'));
const provenance=benchmarkProvenance(inputs.map(digest),{workers:[1],evidenceMode:'typed decoding of 48 preloaded real games; no simulation'});
const runs=[];let expected;
for(let repeat=0;repeat<5;repeat++)for(const variant of repeat%2?['after','before']:['before','after']) {
 let ms=0;const hashes=[],begin=performance.now(),cpu=process.cpuUsage();
 for(const input of inputs){const start=performance.now();const parsed=(variant==='before'?before:after)(input);ms+=performance.now()-start;hashes.push(digest(JSON.stringify(parsed)));}
 const fingerprint=digest(JSON.stringify(hashes));
 if(expected!==undefined&&expected!==fingerprint)throw Error('Decoded records changed');expected=fingerprint;
 const row={repeat,variant,ms,batchMs:performance.now()-begin,cpu:process.cpuUsage(cpu),rss:process.memoryUsage().rss,fingerprint};runs.push(row);console.log(JSON.stringify(row));
 await writeFile('.tmp/perf-iterations/decode-property-measurements.json',JSON.stringify({provenance,runs},null,2));
}

