import {readFile,writeFile} from 'node:fs/promises';
import {spawn} from 'node:child_process';
const source='scripts/bot-improvement/game-log.ts';
const before=await readFile('.tmp/perf-iterations/game-log-before-property.ts','utf8');
const after=await readFile(source,'utf8');
await writeFile('.tmp/perf-iterations/game-log-after-property.ts',after);
let child;
const stop=()=>child?.kill('SIGTERM');
process.on('SIGTERM',stop);process.on('SIGINT',stop);
try {
 for(const [i,variant] of ['before','after','after','before'].entries()) {
  await writeFile(source,variant==='before'?before:after);
  await new Promise<void>((resolve,reject)=>{
   child=spawn(process.execPath,['scripts/bot-improvement/benchmark-improvement-workflow.ts','--source','.tmp/typescript-production-200-games-v3/source','--out',`.tmp/perf-iterations/workflow-property-${variant}-${i}`,'--matches','12','--workers','2'],{stdio:'inherit'});
   child.once('error',reject);child.once('exit',code=>code===0?resolve():reject(Error(`Workflow fixture failed ${code}`)));
  });
  child=undefined;
  await writeFile(source,after);
 }
} finally {
 await writeFile(source,after);
 process.off('SIGTERM',stop);process.off('SIGINT',stop);
}

