import {isDeepStrictEqual} from 'node:util';
import {compareNativeRunners} from '../../scripts/bot-improvement/compare-native-runners.ts';
import {parseGameLog} from '../../scripts/bot-improvement/game-log.ts';
const results=[];
for(const [a,b] of [[0,1],[3,2]]) {
 const before=JSON.parse(await readFile(`.tmp/perf-iterations/workflow-property-before-${a}/measurements.json`,'utf8'));
 const after=JSON.parse(await readFile(`.tmp/perf-iterations/workflow-property-after-${b}/measurements.json`,'utf8'));
 if(before.provenance.frozenInputsSha256!==after.provenance.frozenInputsSha256||before.summary!==after.summary||before.losses!==after.losses||before.reports!==after.reports)throw Error('Workflow input or loss coverage changed');
 const comparison=await compareNativeRunners(before.evaluation.output,after.evaluation.output);
 for(let m=1;m<=before.matches;m++)for(let g=1;g<=4;g++) {
