harnesses.workflow-tool-property-version.ts:
/** Diagnostic evaluation + complete mechanical loss-report ingestion; never promotes a bot. */
import { copyFile, mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { parseArgs } from "node:util";
import { performance } from "node:perf_hooks";
import { verifyFrozen } from "./frozen-setup.ts";
import { digest, identity } from "./session-fixtures.ts";
import { prepareTypescriptJob } from "./run-typescript-matches.ts";
import { runTypescriptNative } from "./run-typescript-native.ts";
import { prepareAnalysisSlices } from "./analysis-slices.ts";
import { benchmarkProvenance } from "./benchmark-provenance.ts";
import {
  configureOutputStorage,
  findOutputRoot,
  outputUsage,
  writeOutput,
} from "./output-storage.ts";
import { targetLossView } from "./game-log.ts";
import type { AnalysisBinding } from "./analysis-contract.ts";
import type { EvidenceReference } from "./session-control-contract.ts";

const { values: v } = parseArgs({
  options: {
    source: { type: "string" },
    out: { type: "string" },
    matches: { type: "string", default: "25" },
    workers: { type: "string", default: "2" },
  },
});
const count = Number(v.matches),
  workers = Number(v.workers);
if (
  !v.source ||
  !v.out ||
  !Number.isSafeInteger(count) ||
  count < 1 ||
  count > 25 ||
  !Number.isSafeInteger(workers) ||
  workers < 1
)
  throw Error(
    "Usage: node scripts/bot-improvement/benchmark-improvement-workflow.ts --source FROZEN_SESSION --out FRESH_OUTPUT [--matches 1..25] [--workers 2]",
  );
const out = path.resolve(v.out),
  session = path.join(out, "session"),
  fixturePath = path.join(out, "fixture");
if (await findOutputRoot(path.join(out, ".probe")))
  throw Error("Diagnostic output must be outside an existing budgeted run");
const begin = performance.now();
await mkdir(path.dirname(out), { recursive: true });
await mkdir(out);
await mkdir(session);
await mkdir(fixturePath);
const json = async (file: string) => JSON.parse(await readFile(file, "utf8"));
const sourceConfig = await json(path.join(v.source, "config.json"));
const original = await verifyFrozen(sourceConfig.fixture.path);
if (count > original.matches.length)
  throw Error("Source fixture has too few matches");
// Copy only verified inputs; the source fixture and production session stay read-only.
for (const file of Object.keys(original.files)) {
  const destination = path.join(fixturePath, file);
  await mkdir(path.dirname(destination), { recursive: true });
  await copyFile(path.join(sourceConfig.fixture.path, file), destination);
}
const { identity: _originalIdentity, ...body } = original;
const narrowed = { ...body, matches: body.matches.slice(0, count) };
const frozen = { ...narrowed, identity: identity(narrowed) };
await writeFile(
  path.join(fixturePath, "manifest.json"),
  JSON.stringify(frozen),
);
await verifyFrozen(fixturePath);
const fixture = { path: fixturePath, identity: frozen.identity };
const accepted = {
  path: path.join(fixturePath, "versions/initial"),
  identity: frozen.target.identity,
};
const config = {
  ...sourceConfig,
  fixture,
  accepted,
  analysisTiming: "after-evaluation",
  limits: {
    ...sourceConfig.limits,
    matchWorkers: workers,
    analysisWorkers: 10,
    stop: { ...sourceConfig.limits.stop, maxBytes: 50_000_000_000 },
  },
};
await writeFile(path.join(session, "config.json"), JSON.stringify(config));
await writeFile(
  path.join(session, "state.json"),
  JSON.stringify({
    schemaVersion: 1,
    status: "ready",
    iteration: 0,
    accepted,
    fixtureIdentity: frozen.identity,
    completedMatches: [],
    completedGames: [],
    stoppingReason: null,
  }),
);
await mkdir(path.join(session, "iterations/iteration-0001"), {
  recursive: true,
});
await writeFile(
  path.join(session, "iterations/iteration-0001/manifest.json"),
  JSON.stringify({
    schemaVersion: 1,
    iteration: 1,
    fixture,
    self: { identity: frozen.target.identity },
    control: { identity: frozen.target.identity },
    opponents: frozen.opponents.map((bot, i) => ({
      slot: `opponent-${i + 1}`,
      identity: bot.identity,
    })),
    runnerIdentity: "diagnostic-workflow-only",
  }),
);
await writeFile(
  path.join(session, "proposal.txt"),
  "Mechanical performance fixture only; no AI findings or promotion.\n",
);
await configureOutputStorage(session, config.limits.stop.maxBytes);
const { job } = await prepareTypescriptJob(session, count);
const setupMs = performance.now() - begin;
const provenanceStart = performance.now();
const provenance = benchmarkProvenance(
  {
    fixture: frozen.identity,
    execution: job.identity,
    matches: count,
    workers,
  },
  {
    workers: [workers],
    evidenceMode:
      "full native evaluation, complete loss preparation and mechanical unclear reports; no analyst inference or replay",
  },
);
const provenanceMs = performance.now() - provenanceStart;
const options = {
  job,
  out: path.join(session, "evaluation"),
  workers,
  maxWallMs: 600000,
  maxBytes: config.limits.stop.maxBytes,
};
const evaluationStart = performance.now();
const evaluation = await runTypescriptNative(options);
const evaluationMs = performance.now() - evaluationStart;
if (
  evaluation.status !== "completed" ||
  evaluation.completedGames !== count * 4 ||
  evaluation.reservedGames !== count * 4
)
  throw Error(
    "Integrated fixture requires every scheduled game to complete without extra reservations",
  );
const ref = async (relative: string): Promise<EvidenceReference> => ({
  path: relative,
  sha256: digest(await readFile(path.join(session, relative))),
});
const relativeOutput = path
  .relative(session, evaluation.output)
  .split(path.sep)
  .join("/");
const binding: AnalysisBinding = {
  iteration: 1,
  role: "candidate",
  root: relativeOutput,
  execution: await ref(`${relativeOutput}/execution.json`),
  proposal: await ref("proposal.txt"),
};
const preparationStart = performance.now();
let state = await prepareAnalysisSlices(session, { action: "sync", binding });
const preparationMs = performance.now() - preparationStart;
let claimMs = 0,
  reportGenerationMs = 0,
  reportIngestionMs = 0,
  losses = 0,
  reports = 0;
const views: { source: string; view: EvidenceReference }[] = [];
while (!state.complete) {
  const claimStart = performance.now();
  const claim = (
    await prepareAnalysisSlices(session, {
      action: "claim",
      iteration: 1,
      role: "candidate",
      owner: "mechanical-fixture",
    })
  ).claim;
  claimMs += performance.now() - claimStart;
  if (!claim?.claim) throw Error("Missing fixture slice claim");
  const generationStart = performance.now();
  const packet = (await json(path.join(session, claim.packet.path))) as {
    jobs: {
      id: string;
      match: string;
      packetSha256: string;
      losses: { game: number; log: EvidenceReference }[];
    }[];
  };
  const submitted: EvidenceReference[] = [];
  for (const item of packet.jobs) {
    const relative = `mechanical-reports/${item.match}.md`;
    const text =
      `# Mechanical fixture — not an AI review\nJob: ${item.id}\nPacket: ${item.packetSha256}\n\n` +
      item.losses
        .map(
          (loss) =>
            `- G${loss.game} | - | unclear | Fixture only | No causal claim\n`,
        )
        .join("");
    await writeOutput(path.join(session, relative), text, true);
    submitted.push(await ref(relative));
    reports++;
    for (const loss of item.losses) {
      losses++;
      views.push({
        source: `${relativeOutput}/matches/${item.match}/native/games/game-${loss.game}/game.log`,
        view: loss.log,
      });
    }
  }
  reportGenerationMs += performance.now() - generationStart;
  const ingestionStart = performance.now();
  state = await prepareAnalysisSlices(session, {
    action: "complete",
    iteration: 1,
    role: "candidate",
    slice: claim.id,
    token: claim.claim.token,
    reports: submitted,
  });
  reportIngestionMs += performance.now() - ingestionStart;
}
if (!state.summary) throw Error("Missing consolidated fixture summary");
const workflowMs = performance.now() - evaluationStart;
// Verification below is reported separately, not hidden inside preparation timings.
const validationStart = performance.now();
for (const item of views) {
  const source = await readFile(path.join(session, item.source), "utf8");
  const view = await readFile(path.join(session, item.view.path), "utf8");
  if (digest(view) !== item.view.sha256 || view !== targetLossView(source))
    throw Error("Analyst view differs from permitted target-loss projection");
}
const resumeStart = performance.now();
const resume = await runTypescriptNative({ ...options, resume: true });
const resumeMs = performance.now() - resumeStart;
if (resume.completedGames !== count * 4 || resume.reservedGames !== count * 4)
  throw Error("Completed resume changed game reservations");
const verificationMs = performance.now() - validationStart;
const usage = await outputUsage(session, true);
const summary = await readFile(path.join(session, state.summary.path), "utf8");
if (!summary.includes(`${losses} losses reviewed · ${losses} unclear`))
  throw Error("Summary coverage differs from fixture reports");
const totalBeforeReportMs = performance.now() - begin;
const report = {
  schemaVersion: 1,
  provenance,
  sourceFixture: original.identity,
  fixture: frozen.identity,
  matches: count,
  games: evaluation.completedGames,
  losses,
  reports,
  stages: {
    setupMs,
    provenanceMs,
    totalBeforeReportMs,
    workflowOverheadMs:
      workflowMs -
      evaluationMs -
      preparationMs -
      claimMs -
      reportGenerationMs -
      reportIngestionMs,
    accountingAndSummaryMs:
      totalBeforeReportMs -
      setupMs -
      provenanceMs -
      workflowMs -
      verificationMs,
    evaluationMs,
    preparationMs,
    claimMs,
    reportGenerationMs,
    reportIngestionMs,
    workflowMs,
    verificationMs,
    resumeMs,
  },
  evaluation,
  resume,
  usage,
  summary,
  stateSummary: state.summary,
  viewsVerified: views.length,
  limitations:
    "One diagnostic run, at most 25 matches. Mechanical unclear reports exercise complete ingestion without making AI findings. Setup includes input verification/copying and job preparation. Workflow includes evaluation, full loss preparation, claims, report generation and ingestion. Verification/resume and provenance capture are separate. No calibration, analyst inference, rule selection, replay, aggregation/promotion or sustained-throughput claim.",
};
await writeFile(
  path.join(out, "measurements.json"),
  JSON.stringify(report, null, 2),
);
console.log(
  JSON.stringify({ out, matches: count, losses, stages: report.stages }),
);

sources.game-log-before-property.ts:
import type {
  ReplayEntry,
  ReplayRecord,
} from "../bot-evaluation/decision-replay.ts";
import type { Artifact } from "../bot-evaluation/host-inputs.ts";
import type { FrozenSetup, MatchExecutionLimits } from "./session-contract.ts";
import type { ParsedDeck } from "../../src/battle/duel/presets/deck-parser.ts";
/** Lossless, typed text records. JSON is used only to escape scalar strings. */
export type LogValue =
  null | boolean | number | string | LogValue[] | { [key: string]: LogValue };
export interface LogLine {
  tag: string;
  value: LogValue;
}
const part = (key: string) =>
  key.replaceAll("~", "~0").replaceAll("/", "~1").replaceAll("=", "~2");
export function encodeLogRecord(tag: string, value: unknown): string {
  if (!/^[A-Z_]+$/.test(tag)) throw Error("Invalid log record tag");
  const fields: string[] = [];
  const visit = (v: unknown, pointer: string) => {
    const token =
      v === null
        ? "z"
        : Array.isArray(v)
          ? "a"
          : typeof v === "object"
            ? "o"
            : typeof v === "string"
              ? `s:${JSON.stringify(v)}`
              : typeof v === "boolean"
                ? `b:${Number(v)}`
                : typeof v === "number" && Number.isFinite(v)
                  ? `n:${v}`
                  : null;
    if (token === null) throw Error("Unsupported log value");
    fields.push(`${pointer}=${token}`);
    if (v && typeof v === "object")
      for (const [k, x] of Object.entries(v)) visit(x, `${pointer}/${part(k)}`);
  };
  visit(value, "");
  return `${tag}\t${fields.join("\t")}\n`;
}
export function decodeLogRecord(line: string): LogLine {
  const [tag, ...fields] = line.split("\t");
  return decodeFields(tag, fields);
}
function decodeFields(
  tag: string | undefined,
  fields: string[],
  dictionary?: string[],
): LogLine {
  if (!tag || !/^[A-Z_]+$/.test(tag) || !fields.length)
    throw Error("Invalid log record");
  const nodes = new Map<string, LogValue>();
  for (const field of fields) {
    const at = field.indexOf("=");
    if (at < 0) throw Error("Malformed log field");
    let pointer = field.slice(0, at);
    const token = field.slice(at + 1);
    if (dictionary) {
      if (
        !/^#(0|[1-9][0-9]*)$/.test(pointer) ||
        dictionary[Number(pointer.slice(1))] === undefined
      )
        throw Error("Unknown log field alias");
      pointer = dictionary[Number(pointer.slice(1))]!;
    }
    if (nodes.has(pointer) || (pointer !== "" && !pointer.startsWith("/")))
      throw Error("Duplicate or invalid log field");
    let value: LogValue;
    if (token === "o") value = {};
    else if (token === "a") value = [];
    else if (token === "z") value = null;
    else if (token === "b:0" || token === "b:1") value = token === "b:1";
    else if (token.startsWith("s:")) {
      value = JSON.parse(token.slice(2));
      if (typeof value !== "string") throw Error("Invalid string field");
    } else if (
      token.startsWith("n:") &&
      /^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$/.test(token.slice(2)) &&
      Number.isFinite(Number(token.slice(2)))
    )
      value = Number(token.slice(2));
    else throw Error("Invalid log field type");
    if (pointer !== "") {
      const slash = pointer.lastIndexOf("/"),
        parent = nodes.get(pointer.slice(0, slash));
      const key = pointer
        .slice(slash + 1)
        .replaceAll("~2", "=")
        .replaceAll("~1", "/")
        .replaceAll("~0", "~");
      if (!parent || typeof parent !== "object")
        throw Error("Missing log field parent");
      if (Array.isArray(parent)) {
        if (!/^(0|[1-9][0-9]*)$/.test(key) || Number(key) !== parent.length)
          throw Error("Invalid log array index");
        parent.push(value);
      } else
        Object.defineProperty(parent, key, {
          value,
          writable: true,
          enumerable: true,
          configurable: true,
        });
    } else if (nodes.size) throw Error("Log root must come first");
    nodes.set(pointer, value);
  }
  if (!nodes.has("")) throw Error("Missing log root");
  return { tag, value: nodes.get("")! };
}
export function decodeLog(text: string, header: string): LogLine[] {
  const lines = text.split("\n");
  if (lines.shift() !== header || lines.pop() !== "")
    throw Error("Invalid or truncated log header/footer");
  let fields: string[] | undefined;
  if (lines[0]?.startsWith("FIELDS\t")) {
    const dictionary = decodeLogRecord(lines.shift()!);
    if (
      !Array.isArray(dictionary.value) ||
      dictionary.value.some((v) => typeof v !== "string") ||
      new Set(dictionary.value).size !== dictionary.value.length
    )
      throw Error("Invalid log field dictionary");
    fields = dictionary.value as string[];
  }
  return lines.map((line) => {
    if (!fields) return decodeLogRecord(line);
    const [tag, ...values] = line.split("\t");
    return decodeFields(tag, values, fields);
  });
}
export interface LogObject {
  [key: string]: LogValue;
}
export interface LoggedDeck {
  [section: string]: {
    card: { card_code: string | number; copies: string | number }[];
  };
}
export interface LoggedInitial {
  [key: string]: unknown;
  own_configuration?: LoggedDeck;
  own_starting_order?: {
    main?: { card: (number | string)[] };
    extra?: { card: (number | string)[] };
  };
}
export interface LoggedResult {
  [key: string]: unknown;
  outcome?: string | null;
  evidence_sha256?: string | null;
}
export interface LoggedGame extends Record<string, unknown> {
  game_id: string;
  status: string;
  number?: number | string;
  stage: string;
  starter: string;
  winner: string | null;
  draw: boolean | null;
}
export interface LoggedActor extends ReplayRecord, Record<string, unknown> {
  game_id: string;
  status: string;
  stage: string;
  starting_player: string;
  initial: LoggedInitial | null;
  result: LoggedResult | null;
}
export interface PreparedMatchItem {
  match: FrozenSetup["matches"][number];
  decks: ParsedDeck[];
  identities: string[];
  bots: (Artifact & { wasm?: string })[];
}
export interface PreparedMatchJob {
  fixtureIdentity: string;
  content: string;
  engine: string;
  engineHash: string;
  profile: string;
  limits: MatchExecutionLimits;
  matches: PreparedMatchItem[];
  schedule?: string;
}
export interface GameLog {
  neutral: LoggedGame;
  actors: [LoggedActor, LoggedActor];
  sideboarding: [LogObject, LogObject];
}
function object(value: LogValue, label: string): LogObject {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw Error(`Invalid ${label} log object`);
  return value;
}
function optionalObject(value: LogValue, label: string): LogObject | null {
  return value === null ? null : object(value, label);
}
/** Complete game records exist only in memory after parsing their authoritative log. */
export function parseGameLog(text: string): GameLog {
  const lines = decodeLog(text, "ASCENCIO_GAME_LOG\t2");
  const next = (tag: string) => {
    const line = lines.shift();
    if (line?.tag !== tag) throw Error(`Expected ${tag} log record`);
    return line.value;
  };
  const neutralObject = object(next("GAME"), "game");
  if (
    typeof neutralObject.game_id !== "string" ||
    typeof neutralObject.status !== "string" ||
    typeof neutralObject.stage !== "string" ||
    typeof neutralObject.starter !== "string"
  )
    throw Error("Invalid game log identity");
  const neutral = neutralObject as unknown as LoggedGame;
  const actors: LoggedActor[] = [],
    sideboarding: LogObject[] = [];
  for (const actor of ["a", "b"]) {
    if (next("ACTOR") !== actor) throw Error("Invalid actor order");
    const header = object(next("RECORD"), "actor");
    sideboarding.push(object(next("SIDEBOARD"), "sideboarding"));
    const initial = optionalObject(next("INITIAL"), "initial");
    const entry: ReplayEntry[] = [];
    while (lines[0]?.tag === "EVENT") {
      const event = object(next("EVENT"), "event");
      if (typeof event.kind !== "string") throw Error("Invalid event kind");
      entry.push(event as ReplayEntry);
    }
    const result = optionalObject(next("RESULT"), "result");
    const record = {
      ...header,
      initial,
      timeline: { entry },
      result,
    } as unknown as LoggedActor;
    if (next("END_ACTOR") !== actor) throw Error("Truncated actor log");
    actors.push(record);
  }
  if (next("END_GAME") !== neutral.game_id || lines.length)
    throw Error("Truncated or trailing game log");
  return {
    neutral,
    actors: actors as [LoggedActor, LoggedActor],
    sideboarding: sideboarding as [LogObject, LogObject],
  };
}
export function targetLossView(text: string): string {
  const { neutral, actors, sideboarding } = parseGameLog(text);
  if (
    neutral.status !== "completed" ||
    neutral.winner !== "b" ||
    neutral.draw !== false ||
    actors[0].result?.outcome !== "loss"
  )
    throw Error("Only completed target losses may be published to analysts");
  const own = actors[0];
  return (
    "ASCENCIO_LOSS_LOG\t2\n" +
    encodeLogRecord("GAME", {
      game_id: neutral.game_id,
      stage: neutral.stage,
      starter: neutral.starter,
      outcome: "loss",
    }) +
    encodeLogRecord("SIDEBOARD", sideboarding[0]) +
    encodeLogRecord("INITIAL", own.initial) +
    own.timeline.entry
      .map((e: unknown) => encodeLogRecord("EVENT", e))
      .join("") +
    encodeLogRecord("RESULT", own.result) +
    encodeLogRecord("END_GAME", neutral.game_id)
  );
}
export interface MatchLog {
  match: LogObject;
  manifest: LogObject;
  fixture: LogObject;
  reports: [LogObject, LogObject];
  refs: LogObject[];
}
export function parseMatchLog(text: string): MatchLog {
  const lines = decodeLog(text, "ASCENCIO_MATCH_LOG\t2");
  const one = (tag: string) => {
    const values = lines.filter((l) => l.tag === tag);
    if (values.length !== 1) throw Error(`Missing/duplicate ${tag}`);
    return values[0]!.value;
  };
  const match = object(one("MATCH"), "match");
  if (one("END_MATCH") !== match.match_id) throw Error("Truncated match log");
  const refs = lines
    .filter((l) => l.tag === "GAME_REF")
    .map((l, i) => {
      const r = object(l.value, "game reference");
      if (r.number !== i + 1 || r.path !== `games/game-${i + 1}/game.log`)
        throw Error("Invalid match game reference");
      return r;
    });
  return {
    match,
    manifest: object(one("MANIFEST"), "manifest"),
    fixture: object(one("FIXTURE"), "fixture"),
    reports: [
      object(one("REPORT_A"), "report a"),
      object(one("REPORT_B"), "report b"),
    ] as [LogObject, LogObject],
    refs,
  };
}

