    encodeLogRecord("SIDEBOARD", sideboarding[0]) +
    encodeLogRecord("INITIAL", own.initial) +
    own.timeline.entry
      .map((e: unknown) => encodeLogRecord("EVENT", e))
      .join("") +
    encodeLogRecord("RESULT", own.result) +
    encodeLogRecord("END_GAME", neutral.game_id)
