    match,
    manifest: object(one("MANIFEST"), "manifest"),
    fixture: object(one("FIXTURE"), "fixture"),
    reports: [
      object(one("REPORT_A"), "report a"),
      object(one("REPORT_B"), "report b"),
    ] as [LogObject, LogObject],
    refs,
  };
}

