    "ASCENCIO_LOSS_LOG\t2\n" +
    encodeLogRecord("GAME", {
      game_id: neutral.game_id,
      stage: neutral.stage,
      starter: neutral.starter,
      outcome: "loss",
    }) +
    encodeLogRecord("SIDEBOARD", sideboarding[0]) +
    encodeLogRecord("INITIAL", own.initial) +
    own.timeline.entry
