export function canonicalTree(v: unknown, evidence = false): unknown {
  if (Array.isArray(v)) return v.map((x) => canonicalTree(x, evidence));
  if (v && typeof v === "object")
    return Object.fromEntries(
      Object.keys(v)
        .sort()
        .filter((k) => {
          const x = (v as Obj)[k];
          return (
            !(Array.isArray(x) && !x.length) &&
            !(
              evidence &&
              (k.endsWith("_sha256") ||
                k.endsWith("_path") ||
                [
                  "bug_id",
                  "duration_ms",
                  "engine_time_ms",
                  "bot_time_ms",
                  "bridge_time_ms",
                  "captured_at",
                  "created_at",
                  "updated_at",
                  "path",
                ].includes(k))
            )
