      const counts = new Map<string, number>();
      for (const code of deck[section])
        counts.set(String(code), (counts.get(String(code)) ?? 0) + 1);
      return [
        section,
        {
          card: [...counts]
            .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
