  return (
    header +
    "\n" +
    encodeLogRecord("FIELDS", fields) +
    lines
      .map((line) => {
        const [tag, ...values] = line.split("\t");
        return [
          tag,
          ...values.map((v) => {
            const i = v.indexOf("=");
            return `#${ids.get(v.slice(0, i))}=${v.slice(i + 1)}`;
