  for (const [i, a] of g.actors.entries()) {
    const outcome =
      status === "failed"
        ? "failed"
        : g.neutral.winner === null
          ? "draw"
          : g.neutral.winner === (i === 0 ? "a" : "b")
            ? "win"
            : "loss";
