) {
  const m = parseMatchLog(text);
  if (
    m.match.match_id !== item.match.id ||
    m.match.run_id !== job.identity ||
    JSON.stringify(canonicalTree(m.fixture)) !==
      JSON.stringify(canonicalTree(item)) ||
    m.refs.length !== 4
  )
    throw Error("Native match inputs changed");
  return m;
}

