      exchanges: {
        from: string;
        to: string;
        cardCode: number;
        copies: number;
        reason: { code: string; explanation: string };
      }[];
      reason: unknown;
    }[];
    const configurations = frame.configurations as unknown[],
      durations = frame.durations as number[];
