        engine_reason: terminal.engine_reason,
        turns: terminal.turns,
        duration_ms: terminal.duration_ms ?? 0,
        engine_time_ms: terminal.engine_time_ms ?? 0,
        bot_time_ms: terminal.bot_time_ms ?? 0,
        evidence_sha256: null as string | null,
