          id,
          records.map((r) => r.configuration_sha256),
          records,
          category,
        );
    if (!skipped) for (const r of records) r.result.evidence_sha256 = hash;
    this.games.push({
      game_id: id,
      number: index + 1,
      stage,
      starter,
      status: skipped ? "skipped" : "failed",
      winner: null,
      draw: null,
      evidence_sha256: hash,
      bug_id: bug,
      ...(skipped
        ? { skip_reason: category }
