    if(f.type==='event'||f.type==='decision')records[order[f.actor]].timeline.entry.push(mapPlayers(f.entry,order[0]===1));
   }
   const decision=records.flatMap(r=>r.timeline.entry).find(e=>e.kind==='decision');
   const verifier=new DecisionReplay({actor:decision.actor,decision:decision.decision_id,records},order);
   const counts=[0,0];
   for(const f of right) {
    if(f.type==='initial')verifier.initial(f.actor,f.initial);
    if(f.type==='event'||f.type==='decision'){verifier.event(f.actor,f.entry);counts[order[f.actor]]++;}
