/** Experimental worker: engine and frozen content remain local across matches. */
import { parentPort, workerData } from "node:worker_threads";
import { executeHostCommand } from "../bot-evaluation/host.ts";
import type { prepareMatches } from "./prepare-match-job.ts";
import { identity } from "./session-fixtures.ts";
import type { ParsedDeck } from "../../src/battle/duel/presets/deck-parser.ts";
export type Job = Awaited<ReturnType<typeof prepareMatches>>["job"];
export type Frame = {
  type: string;
  actor: number;
  entry: Record<string, unknown>;
  initial: Record<string, unknown>;
  prompt: unknown;
  winner: number | null;
  turns: number;
  engine_reason: string;
  decks: [ParsedDeck, ParsedDeck];
  [key: string]: unknown;
  handles_created: number;
  handles_destroyed: number;
};
export function gameplayHash(value: unknown): string {
  const sort = (v: unknown): unknown =>
    Array.isArray(v)
      ? v.map(sort)
      : v && typeof v === "object"
        ? Object.fromEntries(
            Object.entries(v)
              .sort(([a], [b]) => a.localeCompare(b))
              .map(([k, x]) => [k, sort(x)]),
          )
        : v;
  return identity(sort(value));
}
// Mapping also owns its result: exceptional object-valued role fields must
// not retain host references even though their contents are not seat-mapped.
const copyValue = (value: unknown) =>
  value && typeof value === "object" ? structuredClone(value) : value;
export function mapPlayers(value: unknown, swapped: boolean): unknown {
  if (Array.isArray(value)) return value.map((v) => mapPlayers(v, swapped));
  if (!value || typeof value !== "object") return value;
  const result: Record<string, unknown> = {};
  for (const k of Object.keys(value)) {
    const v = (value as Record<string, unknown>)[k];
    let next;
    if (k === "life_points" && swapped && v && typeof v === "object")
      next = {
        a: copyValue((v as Record<string, unknown>).b),
        b: copyValue((v as Record<string, unknown>).a),
      };
    else if (
      ["actor", "player", "controller", "owner", "turn_player"].includes(k)
    )
      next =
        v === 0
          ? swapped
            ? "b"
            : "a"
          : v === 1
            ? swapped
              ? "a"
              : "b"
            : copyValue(v);
    else next = mapPlayers(v, swapped);
    if (Object.hasOwn(Object.prototype, k))
      Object.defineProperty(result, k, {
        value: next,
        writable: true,
        enumerable: true,
        configurable: true,
      });
    else result[k] = next;
  }
  return result;
}
export async function integratedMatch(
  job: Job,
  item: Job["matches"][number],
  evidence: boolean,
  hooks?: {
    progress?: (frame: Frame) => void;
    sideboard?: (frame: Frame) => void;
    game?: (game: {
      index: number;
      initial: Record<string, unknown>[];
      events: Record<string, unknown>[][];
      terminal: Frame;
      decks: [ParsedDeck, ParsedDeck];
    }) => Promise<void>;
