    await executeHostCommand(value, (raw) => {
      const f = raw as Frame;
      hooks?.progress?.(f);
      if (["host_error", "failure", "fallback"].includes(f.type))
        throw Error(JSON.stringify(f));
      if (evidence) frames.push(structuredClone(f));
      consume(f);
    });
  };
