    {
      type: "initialize",
      snapshot: job.content,
      codes: [],
      bots: [],
      frozen: { bots: item.bots, engine: job.engine },
    },
    () => {},
  );
  for (let index = 0; index < 4; index++) {
    hooks?.progress?.({
      type: index === 2 ? "sideboard_start" : "game_start",
    } as Frame);
