      cleaned = false,
      prompt: unknown;
    await command(
      {
        type: "game",
        game_id: `${item.match.id}-game-${index + 1}`,
        profile: job.profile,
        limits: job.limits,
        decks: order.map((i) => decks[i]),
        orders: null,
