}
interface SliceState {
  schemaVersion: 1;
  binding: AnalysisBinding;
  executionIdentity: string;
  slices: Slice[];
}
export type SliceAction =
  | { action: "sync"; binding: AnalysisBinding }
  | ({ iteration: number; role: AnalysisBinding["role"] } & (
      | { action: "status" }
      | { action: "claim"; owner: string }
