    number: number;
    id: string;
    status: "completed" | "failed" | "skipped";
    evidenceHash: string | null;
  }[] = [];
  const outcomes: (
    "win" | "loss" | "draw" | "failed" | "skipped" | "timeout"
  )[] = [];
