      g.game_id !== `${expected.match}-game-${n}` ||
      g.number !== n ||
      !["completed", "failed", "skipped"].includes(status) ||
      g.stage !== (n < 3 ? "pre_side" : "post_side") ||
      g.starter !== (n % 2 ? "a" : "b")
    )
      throw new Error("Invalid native game identity/status");
