    ...limits,
    ...usage,
    stopped,
    exhausted:
      stopped ||
      usage.totalBytes >= limits.maxBytes - limits.controlReserveBytes,
  };
}
/** Stage + fsync + atomic publish; staging bytes count against the appropriate quota. */
export async function writeOutput(
  file: string,
  bytes: string | Uint8Array,
  exclusive = false,
) {
