  try {
    const [session, request] = process.argv.slice(2);
    if (!session || !request)
      throw new Error("Usage: npm run bot:analyses -- SESSION REQUEST.json");
    console.log(
      JSON.stringify(await prepareAnalyses(session, await json(request))),
    );
  } catch (error) {
    console.error(String(error));
    process.exitCode = 1;
  }
}

