      text += encodeLogRecord(`REPORT_${a.toUpperCase()}`, {
        run_id: job.identity,
        match_id: id,
        perspective: a,
        bot_artifact_sha256: item.identities[i],
        sideboarding: this.sideboarding[i] ?? {
          status: "skipped",
