import {readFile,writeFile} from 'node:fs/promises';
import {spawn,spawnSync} from 'node:child_process';
const base='6faef29a95820d0dc0467ffb4457f1b6409fb7fb';
const index=Number(process.argv[2]),variants=['before','after','after','before'] as const;
if(!Number.isInteger(index)||index<0||index>3)throw Error('Run index 0..3 required');
const snapshot='.tmp/perf-iterations/workflow-combined-sources.json';
let sources:{file:string,before:string,after:string}[];
try {sources=JSON.parse(await readFile(snapshot,'utf8')).sources;}
catch(e) {
 if(e.code!=='ENOENT'||index!==0)throw e;
 const list=spawnSync('git',['diff','--name-only',base,'--','scripts/bot-improvement'],{encoding:'utf8'});
 if(list.status!==0)throw Error(list.stderr);
 sources=[];
 for(const file of list.stdout.trim().split('\n').filter(Boolean)){
  const old=spawnSync('git',['show',`${base}:${file}`],{encoding:'utf8'});
  if(old.status!==0)throw Error(old.stderr);
  sources.push({file,before:old.stdout,after:await readFile(file,'utf8')});
 }
 await writeFile(snapshot,JSON.stringify({base,sources},null,2));
}
async function install(variant:'before'|'after'){
 for(const item of sources){
  const current=await readFile(item.file,'utf8');
  if(current!==item.before&&current!==item.after)throw Error(`Concurrent edit preserved: ${item.file}`);
  await writeFile(item.file,item[variant]);
 }
}
let child;
const stop=()=>child?.kill('SIGTERM');
process.on('SIGINT',stop);process.on('SIGTERM',stop);
try{
 const variant=variants[index]!;
 await install(variant);
 await new Promise<void>((resolve,reject)=>{
  child=spawn(process.execPath,['scripts/bot-improvement/benchmark-improvement-workflow.ts','--source','.tmp/typescript-production-200-games-v3/source','--out',`.tmp/perf-iterations/workflow-combined-${variant}-${index}`,'--matches','25','--workers','2'],{stdio:'inherit'});
  child.once('error',reject);child.once('exit',code=>code===0?resolve():reject(Error(`Combined comparison failed ${code}`)));
